('makes switching cheaper later.', 'can reduce call-site changes, but migration cost also depends on data and semantic compatibility.'),
('    for f in root.rglob("*.py"):', '    files = list(root.rglob("*.py"))\n    assert files, "no domain files found"\n    for f in files:'),
